    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel Province {\n  id        String   @id @default(uuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  users     User[]\n}\n\nenum UserRole {\n  ADMIN\n  RESPONSABLE_PROVINCIAL\n  MEMBRE\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  fullName     String\n  email        String   @unique\n  passwordHash String\n  role         UserRole @default(MEMBRE)\n  isActive     Boolean  @default(true)\n\n  provinceId String?\n  province   Province? @relation(fields: [provinceId], references: [id])\n\n  createdAt          DateTime                 @default(now())\n  updatedAt          DateTime                 @updatedAt\n  emailVerifiedAt    DateTime?\n  verificationTokens EmailVerificationToken[]\n  sessions           RefreshSession[]\n}\n\nmodel EmailVerificationToken {\n  id         String    @id @default(uuid())\n  tokenHash  String    @unique\n  userId     String    @unique\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt  DateTime\n  consumedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@index([expiresAt])\n}\n\nmodel RefreshSession {\n  id     String @id @default(uuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  tokenHash  String    @unique\n  expiresAt  DateTime\n  revokedAt  DateTime?\n  lastUsedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nenum OpinionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nmodel Opinion {\n  id            String        @id @default(uuid())\n  authorName    String?\n  isAnonymous   Boolean       @default(false)\n  content       String\n  status        OpinionStatus @default(PENDING)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n  publicationId String?\n  publication   Publication?  @relation(fields: [publicationId], references: [id], onDelete: Restrict)\n\n  @@index([status, createdAt])\n}\n\nenum PublicationType {\n  DOCUMENT\n  DOCTRINE\n}\n\nenum PublicationStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nmodel Publication {\n  id          String            @id @default(uuid())\n  title       String\n  description String?\n  type        PublicationType\n  status      PublicationStatus @default(DRAFT)\n\n  doctrineNumber  Int?\n  doctrineVersion String?\n\n  fileName   String?\n  storageKey String?\n  mimeType   String?\n  fileSize   Int?\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  publishedAt DateTime?\n\n  opinions Opinion[]\n\n  @@index([type, status, publishedAt])\n  @@index([doctrineNumber, doctrineVersion])\n}\n",
